GLuint g_VBO = 0;

// Player state
float g_PosX = 0.0f;
float g_PosY = 0.0f;
float g_VelY = 0.0f;
bool g_IsGrounded = true;
float g_PlayerScale = 0.15f;

// GLSL 3.00 ES Shader Sources
const char* vsSrc = R"(#version 300 es
layout (location = 0) in vec2 aPos;
uniform vec2 uOffset;
uniform vec2 uScale;
