        if (typeof FS !== 'undefined') {
            try {
                var bytes = FS.readFile(path);
                var mime = path.endsWith('.mp3') ? 'audio/mpeg' : (path.endsWith('.ogg') ? 'audio/ogg' : 'audio/wav');
                var blob = new Blob([bytes], {type: mime});
                url = URL.createObjectURL(blob);
